-- MP-0005: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='bersatu' and type='party') then raise exception 'MP-0005: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0005: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('sabri-azit','ahmad-tarmizi-sulaiman','mohd-nazri-abu-hassan') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0005: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('jerai','sik','merbok') and slug not in ('sabri-azit','ahmad-tarmizi-sulaiman','mohd-nazri-abu-hassan')) then raise exception 'MP-0005: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0005:%' and (m.source_type <> 'editorial' or e.slug not in ('sabri-azit','ahmad-tarmizi-sulaiman','mohd-nazri-abu-hassan') or m.import_key not like 'MP-0005:' || e.slug || ':%')) then raise exception 'MP-0005: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'sabri-azit','Sabri Azit','opposition','Member of the Dewan Rakyat','Jerai','Kedah','Sabri Azit represents Jerai, Kedah, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4051','/portraits/sabri-azit.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P012.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4051"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'ahmad-tarmizi-sulaiman','Ahmad Tarmizi Sulaiman','opposition','Member of the Dewan Rakyat','Sik','Kedah','Ahmad Tarmizi Sulaiman represents Sik, Kedah, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4052','/portraits/ahmad-tarmizi-sulaiman.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P013.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4052"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'mohd-nazri-abu-hassan','Mohd Nazri Abu Hassan','opposition','Member of the Dewan Rakyat','Merbok','Kedah','Mohd Nazri Abu Hassan represents Merbok, Kedah, in the Dewan Rakyat. A Bersatu member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4053','/portraits/mohd-nazri-abu-hassan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P014.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4053"}, {"label": "Reported Bersatu affiliation · 29 Oct 2026 CSA signatories", "url": "https://bernama.com/bm/am/news.php?id=2627381"}]'::jsonb from public.entities parent where parent.slug='bersatu' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('sabri-azit','ahmad-tarmizi-sulaiman','mohd-nazri-abu-hassan') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0005: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0005:sabri-azit:jawi-courses','Provide intensive Jawi-writing courses for teachers in Jerai','Education','in_progress',null,null,null,null,'2024-08-13','https://harakahdaily.net/2024/08/13/ahli-parlimen-jerai-komited-martabat-tulisan-jawi/','Sabri described Saturday training courses at his parliamentary service centre.','Two intake series were reported completed, with a third planned. This is an August 2024 activity snapshot; later continuation and a total-course target were not established. No percentage is inferred.','2026-11-09','editorial',false from public.entities e where e.slug='sabri-azit' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0005:sabri-azit:allowance-welfare','Continue directing part of the MP’s allowance to constituency welfare','Social welfare','in_progress',null,null,'2026-09-20','https://www.utusan.com.my/nasional/2026/09/sabri-azit-peruntuk-30-peratus-elaun-untuk-kebajikan-rakyat-jerai/','2026-09-20','https://www.utusan.com.my/nasional/2026/09/sabri-azit-peruntuk-30-peratus-elaun-untuk-kebajikan-rakyat-jerai/','Sabri said he allocated about 30% of his monthly allowance to residents in need and would continue during his second term.','The interview is a self-described ongoing practice, not an audited expenditure account. The 30% is a share of allowance, not a completion score; verified spending totals and full-term fulfilment remain unavailable.','2026-11-09','editorial',false from public.entities e where e.slug='sabri-azit' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

